// Applies SQL migrations (src/db/migrations, generated by drizzle-kit) in order, once each.
// Usage: DATABASE_URL_OWNER=postgres://owner:...@host/db node scripts/migrate.mjs [--roles]
//   --roles also (re)applies src/db/roles.sql; set READ_PASSWORD and WRITE_PASSWORD.
import { readFileSync } from "node:fs";
import pg from "pg";

export async function migrate(url, { roles = false, readPassword, writePassword, log = console.log } = {}) {
  const c = new pg.Client({ connectionString: url });
  await c.connect();
  try {
    await c.query("create table if not exists _migrations (name text primary key, applied_at timestamptz default now())");
    const journal = JSON.parse(readFileSync(new URL("../src/db/migrations/meta/_journal.json", import.meta.url), "utf8"));
    for (const e of journal.entries) {
      if ((await c.query("select 1 from _migrations where name = $1", [e.tag])).rowCount) continue;
      await c.query("begin");
      try {
        for (const stmt of readFileSync(new URL(`../src/db/migrations/${e.tag}.sql`, import.meta.url), "utf8").split("--> statement-breakpoint")) if (stmt.trim()) await c.query(stmt);
        await c.query("insert into _migrations(name) values ($1)", [e.tag]);
        await c.query("commit");
        log(`applied ${e.tag}`);
      } catch (err) { await c.query("rollback"); throw err; }
    }
    if (roles) {
      if (!readPassword || !writePassword) throw new Error("Set READ_PASSWORD and WRITE_PASSWORD to apply roles.");
      await c.query(readFileSync(new URL("../src/db/roles.sql", import.meta.url), "utf8").replace("change-me-read", readPassword.replace(/'/g, "''")).replace("change-me-write", writePassword.replace(/'/g, "''")));
      log("roles applied");
    }
  } finally { await c.end(); }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const url = process.env.DATABASE_URL_OWNER;
  if (!url) { console.error("Set DATABASE_URL_OWNER (the database owner connection string)."); process.exit(1); }
  await migrate(url, { roles: process.argv.includes("--roles"), readPassword: process.env.READ_PASSWORD, writePassword: process.env.WRITE_PASSWORD });
}
